js_body:
log("slot-watch js_body starting");

registerTool({
  name: "echo",
  description: "Echo JSON args back (JS demo)",
  schema: { type: "object", properties: { msg: { type: "string" } } },
  handler: function (args) {
    return { ok: true, echo: args };
  }
});

registerTool({
  name: "add",
  description: "Add args.a + args.b (JS demo)",
  schema: {
    type: "object",
    properties: { a: { type: "number" }, b: { type: "number" } }
  },
  handler: function (args) {
    var a = Number(args && args.a != null ? args.a : 0);
    var b = Number(args && args.b != null ? args.b : 0);
    return { sum: a + b };
  }
});

// Demonstrate readBinding metadata stub (no mem read yet)
var meta = readBinding("n_past");
log("readBinding(n_past) =>", meta);
